## municipalities.json の読み込みユーティリティ
site/src/lib/municipalities.ts を作成:
```typescript
import fs from 'fs';
import path from 'path';

export type Municipality = {
  slug: string;
  name: string;
  council_name: string;
  region: string;
  furigana: string;
  features: string[];
  active: boolean;
  tenant_id: number;
  system: string;
};

export function getMunicipalities(): Municipality[] {
  const fp = path.join(process.cwd(), 'data', 'municipalities.json');
  return JSON.parse(fs.readFileSync(fp, 'utf-8'));
}

export function getMunicipality(slug: string): Municipality | null {
  return getMunicipalities().find(m => m.slug === slug && m.active) ?? null;
}

export function hasFeature(slug: string, feature: string): boolean {
  return getMunicipality(slug)?.features.includes(feature) ?? false;
}
```

## 重要な注意事項
- data/ のパスは process.cwd() + '/data/{city}/...' （site/ から見た相対パス）
- generateStaticParams は必須（静的ビルドのため）
- DESIGN.md のデザインパターンを厳守すること
- TypeScript 型エラーがないこと（npx tsc --noEmit で確認）
- 既存の個別ページは削除しない（この時点では並存させる）
